"use strict";
// Original local play; fictional points and messages, with no real paid services.
const pocketSouvenirs=['玻璃弹珠','公交月票','游戏厅代币','星星折纸','彩色电话卡','海边明信片','透明磁带','毕业留言册','旧车票','四叶草书签','像素徽章','蓝色贝壳'];
function pocketClubLoad(raw){const d={name:'小团',level:1,xp:0,coins:20,energy:6,mood:70,collection:[],notes:[],wins:0,fish:0,best:0};try{const p=JSON.parse(raw||'{}');for(const k of ['level','xp','coins','energy','mood','wins','fish','best'])if(Number.isSafeInteger(p[k])&&p[k]>=0)d[k]=Math.min(p[k],k==='energy'?6:k==='mood'?100:k==='level'?99:99999);if(typeof p.name==='string')d.name=p.name.slice(0,12)||'小团';if(Array.isArray(p.collection))d.collection=[...new Set(p.collection.filter(n=>Number.isInteger(n)&&n>=0&&n<pocketSouvenirs.length))];if(Array.isArray(p.notes))d.notes=p.notes.filter(n=>typeof n==='string').slice(-8).map(n=>n.slice(0,140));}catch{}d.level=Math.max(1,d.level);return d;}
let pocketClub=pocketClubLoad(localStorage.getItem('olddays-pocket-club')),pocketClubPage='home',pocketBattle=null,pocketCast=0,pocketClubNotice='';
function pocketClubSave(){try{localStorage.setItem('olddays-pocket-club',JSON.stringify(pocketClub));}catch{}}
function pocketClubNote(t){pocketClub.notes.push(t);pocketClub.notes=pocketClub.notes.slice(-8);}
function pocketClubXP(n){pocketClub.xp+=n;while(pocketClub.xp>=pocketClub.level*12&&pocketClub.level<99){pocketClub.xp-=pocketClub.level*12;pocketClub.level++;pocketClub.coins+=8;pocketClubNote('小团长大了一点。新等级 '+pocketClub.level+'，收到8枚零花钱。');}}
function pocketClubCollect(index){if(!pocketClub.collection.includes(index)){pocketClub.collection.push(index);pocketClubNote('收到纪念品：'+pocketSouvenirs[index]+'。已放入抽屉。');return true;}pocketClub.coins+=3;return false;}
function pocketClubAction(action,now=Date.now(),random=Math.random){pocketClubNotice='';if(action==='feed'){if(pocketClub.coins<4){pocketClubNotice='零花钱不够，去钓鱼或玩一局赚一点吧。';return false;}pocketClub.coins-=4;pocketClub.energy=Math.min(6,pocketClub.energy+3);pocketClub.mood=Math.min(100,pocketClub.mood+12);pocketClubNotice='热乎乎的饭团！体力 +3，心情 +12。';}
else if(action==='start'){if(!pocketClub.energy){pocketClubNotice='先吃点东西恢复体力。钓鱼不用体力。';return false;}pocketClub.energy--;pocketBattle={stage:1,hp:24+pocketClub.level*4,max:24+pocketClub.level*4,enemy:16,turn:0,potions:2,log:'放学后的旧巷，纸箱怪挡住了去路。'};pocketClubPage='battle';}
else if(['attack','guard','potion','run'].includes(action)){if(!pocketBattle)return false;const b=pocketBattle;if(action==='run'){pocketClubPage='home';pocketBattle=null;pocketClubNotice='带着小团回家了，下次再来。';}
else{b.turn++;if(action==='potion'){if(!b.potions){pocketClubNotice='背包里的两瓶汽水已经喝完。';return false;}b.potions--;b.hp=Math.min(b.max,b.hp+14);b.log='喝了汽水，恢复14点精神。';}else{const damage=action==='guard'?3:6+pocketClub.level+Math.floor(random()*4);b.enemy-=damage;b.log=(action==='guard'?'抱紧书包防守，反击':'小团使出弹珠攻击')+'，造成'+damage+'点伤害。';}if(b.enemy<=0){pocketClub.coins+=8;pocketClubXP(5);if(b.stage===3){pocketClub.wins++;pocketClubCollect(Math.floor(random()*8));pocketClubXP(10);pocketClubNote('和小团一起走完旧巷，路灯亮起来的时候刚好到家。');pocketClubNotice='闯过三站！赢得24枚零花钱、25经验和一件纪念品。';pocketBattle=null;pocketClubPage='home';}else{b.stage++;b.enemy=12+b.stage*5;b.hp=Math.min(b.max,b.hp+7);b.log='过关！捡到8枚零花钱，恢复7点精神。下一站：'+['','纸箱怪','发条青蛙','路灯守卫'][b.stage]+'。';}}else{const hit=action==='guard'?2:4+b.stage+Math.floor(random()*3);b.hp-=hit;b.log+=' 对手反击'+hit+'点。';if(b.hp<=0){pocketClub.coins+=2;pocketClubXP(2);pocketClubNotice='小团累了。路过的店员送你们回家，留下2枚车费。';pocketBattle=null;pocketClubPage='home';}}}}
else if(action==='cast'){pocketCast=now;pocketClubPage='fishing';pocketClubNotice='浮标进入浅色区域时收杆。';}
else if(action==='catch'){if(!pocketCast)return false;const progress=((now-pocketCast)%1800)/1800;pocketCast=0;const caught=progress>=.34&&progress<=.66;if(caught){pocketClub.fish++;pocketClub.coins+=5;pocketClubXP(3);pocketClubCollect(8+Math.floor(random()*4));pocketClubNotice='钓到了！零花钱 +5、经验 +3，看看收藏抽屉。';}else{pocketClub.coins++;pocketClubNotice='鱼溜走了，捡到1枚零花钱。再试一次？';}}
else if(action==='home'){pocketClubPage='home';pocketCast=0;}
else if(action==='collection'||action==='letters'||action==='fishing')pocketClubPage=action;
else return false;pocketClubSave();return true;}
function pocketClubMarkup(){const c=pocketClub,button=(id,t)=>'<button data-pocket-club="'+id+'">'+t+'</button>';let body='';if(pocketClubPage==='battle'&&pocketBattle){const b=pocketBattle;body='<div class="club-battle"><small>旧巷探险 · 第 '+b.stage+' / 3 站</small><div class="club-enemy">'+['','▣','♧','♜'][b.stage]+'</div><b>'+['','纸箱怪','发条青蛙','路灯守卫'][b.stage]+' · '+Math.max(0,b.enemy)+' HP</b><p>小团精神 '+b.hp+' / '+b.max+'</p><meter min="0" max="'+b.max+'" value="'+Math.max(0,b.hp)+'"></meter><p aria-live="polite">'+escapeHTML(b.log)+'</p><div class="club-actions">'+button('attack','1 弹珠攻击')+button('guard','2 书包防守')+button('potion','3 喝汽水 ('+b.potions+')')+button('run','回家')+'</div></div>';}
else if(pocketClubPage==='fishing'){body='<div class="club-lake"><span>☁　　☁</span><strong>⌁　⌁　⌁</strong><p>河边的下午，什么也不用着急。</p></div>'+(pocketCast?'<div class="club-fishing-bar"><i></i><b></b></div>'+button('catch','5 现在收杆！'):button('cast','抛下鱼竿'))+'<p>在浮标经过中间浅色区域时收杆。钓鱼不消耗体力，没钓到也会捡到零花钱。</p>';}
else if(pocketClubPage==='collection'){body='<h3>抽屉里的青春 · '+c.collection.length+' / 12</h3><div class="club-collection">'+pocketSouvenirs.map((t,i)=>'<article class="'+(c.collection.includes(i)?'found':'')+'"><b>'+['◉','▤','◈','★','▧','✉','▣','▥','▤','♧','✣','◔'][i]+'</b><span>'+(c.collection.includes(i)?t:'未找到')+'</span></article>').join('')+'</div><p>探险与河边垂钓，会带回不同的小东西。</p>';}
else if(pocketClubPage==='letters'){body='<h3>小团的来信</h3>'+(c.notes.length?c.notes.slice().reverse().map(n=>'<blockquote>'+escapeHTML(n)+'</blockquote>').join(''):'<blockquote>你好呀。放学以后，你愿意带我出去走走吗？<br>—— 小团</blockquote>');}
else body='<div class="club-pet"><span>✦　　✧</span><strong>(•ᴗ•)</strong><b>'+escapeHTML(c.name)+' · Lv.'+c.level+'</b><small>等你下课的小伙伴</small></div><div class="club-stats"><span>体力 '+c.energy+'/6</span><span>心情 '+c.mood+'/100</span><span>零花钱 '+c.coins+'</span></div><p>经验 '+c.xp+' / '+c.level*12+' · 闯关 '+c.wins+' 次 · 钓鱼 '+c.fish+' 条</p><div class="club-actions">'+button('start','✦ 旧巷探险')+button('fishing','⌁ 河边钓鱼')+button('feed','饭团 · 4零花钱')+button('collection','▤ 收藏抽屉')+button('letters','✉ 小团来信')+'</div><details><summary>怎么玩？</summary><p>探险连闯三站，可攻击、防守、喝汽水；通关涨经验、赚零花钱、收集纪念品。钓鱼考验收杆时机，喂饭恢复体力。进度保存在本机，可随存档盒备份。均为原创网页玩法。</p></details>';
return '<section class="pocket-club"><header><small>POCKET PAL / 原创养成</small><h2>放学别关机</h2>'+button('home','⌂ 小团的家')+'</header>'+body+(pocketClubNotice?'<p class="club-notice" role="status">'+escapeHTML(pocketClubNotice)+'</p>':'')+'<footer>本机存档 · 没有真实消费</footer></section>';}
phoneApps.push(['pocketclub','放学别关机','✦']);systemApps.push({id:'pocketclub',name:'放学别关机',icon:'✦',color:'lime',desc:'养小团、探险战斗、钓鱼和收藏'});systemInstalled.push('pocketclub');
const pocketClubAllowedBase=phoneAppAllowed,pocketClubScreenBase=phoneScreen,pocketClubShelfBase=phoneGameShelfMarkup;
phoneAppAllowed=function(app){return app==='pocketclub'?!isTextOnlyPhone()&&!deviceCapabilities[phoneState.model]:pocketClubAllowedBase(app);};
phoneScreen=function(){return phoneState.app==='pocketclub'&&phoneAppAllowed('pocketclub')?pocketClubMarkup():pocketClubScreenBase();};
phoneGameShelfMarkup=function(){return '<button class="club-entry" data-phone-app="pocketclub"><b>✦ 放学别关机</b><span>养小团 · 回合探险 · 钓鱼 · 收集12件纪念品 →</span></button>'+pocketClubShelfBase();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-pocket-club]');if(!b)return;e.preventDefault();pocketClubAction(b.getAttribute('data-pocket-club'));refreshPhone();});
function pocketClubHardware(key){const action=pocketClubPage==='battle'?({'1':'attack','2':'guard','3':'potion','5':'attack'}[key]):pocketClubPage==='fishing'&&key==='5'?(pocketCast?'catch':'cast'):({'1':'start','2':'fishing','3':'feed','4':'collection','5':'letters'}[key]);if(!action)return false;pocketClubAction(action);refreshPhone();return true;}
document.addEventListener('click',e=>{if(phoneState.app!=='pocketclub')return;const b=e.target.closest('[data-phone-key],[data-phone-ok]');if(!b)return;const key=b.hasAttribute('data-phone-ok')?'5':b.getAttribute('data-phone-key');if(pocketClubHardware(key)){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('keydown',e=>{if(phoneState.app!=='pocketclub'||e.target.matches?.('input,textarea,select'))return;if(pocketClubHardware(e.key==='Enter'?'5':e.key)){e.preventDefault();e.stopImmediatePropagation();}},true);
const pocketClubSmsBase=phoneSmsMarkup;
phoneSmsMarkup=function(){const base=pocketClubSmsBase();if(typeof experienceZone==='undefined'||experienceZone!=='phone'||!pocketClub.notes.length)return base;return '<details class="club-sms"><summary>✉ 放学别关机 · '+pocketClub.notes.length+' 条游戏来信</summary>'+pocketClub.notes.slice(-3).reverse().map(t=>'<p>'+escapeHTML(t)+'</p>').join('')+'<button data-phone-app="pocketclub">打开小团的家 →</button><small>本机游戏消息，非真实短信</small></details>'+base;};
